import{c as r,Q as o,j as n,m as s}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"架构设计方法  概述","description":"","frontmatter":{"title":"架构设计方法  概述"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法/架构设计方法  概述.md","filePath":"综合知识/架构设计/架构设计方法/架构设计方法  概述.md","lastUpdated":null}'),d={name:"综合知识/架构设计/架构设计方法/架构设计方法  概述.md"};function l(g,t,e,a,i,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h3 id="absd-—-基于架构的软件设计" tabindex="-1">ABSD — 基于架构的软件设计 <a class="header-anchor" href="#absd-—-基于架构的软件设计" aria-label="Permalink to &quot;ABSD — 基于架构的软件设计&quot;">​</a></h3><blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行功能分解</li><li>采用<strong>架构策略</strong>实现质量属性与商业需求</li><li>采用软件模板设计软件结构</li></ol><p><strong>六个子过程：</strong></p><ol><li><strong>架构需求</strong> — 获取需求</li><li><strong>架构设计</strong> — 设计方案</li><li><strong>架构文档化</strong> — 输出架构规格说明和测试架构需求的质量设计说明书</li><li><strong>架构复审</strong> — 标识潜在风险，及早发现架构设计中的缺陷和错误</li><li><strong>架构实现</strong> — 编码实现</li><li><strong>架构演化</strong> — 应对需求变化，修改应用架构满足新需求</li></ol><hr><h4 id="架构文档化" tabindex="-1">架构文档化 <a class="header-anchor" href="#架构文档化" aria-label="Permalink to &quot;架构文档化&quot;">​</a></h4><blockquote><p>架构文档化过程的主要输出结果是<strong>架构规格说明书</strong>和<strong>测试架构需求的质量设计说明书</strong>。</p></blockquote><p><strong>文档化原则：</strong></p><ul><li>从使用者的角度书写文档</li><li>随时保证文档是最新的</li><li>将文档分发给相关人员</li><li>针对不同背景的人员书写文档的方式不同</li></ul><hr><h3 id="dssa-—-特定领域软件架构" tabindex="-1">DSSA — 特定领域软件架构 <a class="header-anchor" href="#dssa-—-特定领域软件架构" aria-label="Permalink to &quot;DSSA — 特定领域软件架构&quot;">​</a></h3><blockquote><p>DSSA 是特定应用领域中为一组应用提供组织结构参考的<strong>标准软件架构</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong>，描述领域中系统间的共同需求</td><td>领域模型</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>特定领域软件架构（DSSA）</strong></td><td>领域架构</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织可重用信息，实现基础软件架构</td><td>可重用构件/资产</td></tr></tbody></table><p><strong>四类参与角色：</strong></p><ol><li><strong>领域专家</strong> — 提供领域知识</li><li><strong>领域分析者</strong> — 控制领域分析过程，进行知识获取，组织领域模型</li><li><strong>领域设计者</strong> — 根据领域模型开发领域设计，验证设计的准确性和一致性</li><li><strong>领域实现者</strong> — 实现可重用资产</li></ol><p><strong>DSSA 三级层次：</strong></p><ul><li>领域开发环境 → <strong>应用工程师</strong>主要在领域特定应用开发环境中工作</li><li>领域特定应用开发环境</li><li>应用执行环境</li></ul><p><strong>垂直域 vs 水平域：</strong></p><ul><li><strong>垂直域</strong>：定义了一个特定的系统族，包含整个系统族内的多个系统</li><li><strong>水平域</strong>：定义了多个系统和多个系统族中功能区域的共有部分，在子系统级上涵盖多个系统族</li></ul><hr><h3 id="_4-1-视图模型" tabindex="-1">4+1 视图模型 <a class="header-anchor" href="#_4-1-视图模型" aria-label="Permalink to &quot;4+1 视图模型&quot;">​</a></h3><blockquote><p>4+1 视图模型从多个视图描述软件体系结构，核心思想是<strong>关注点分离</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>作用</th><th>关注点</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>描述对象模型，说明系统应提供哪些服务</td><td>功能需求（用户视角）</td></tr><tr><td><strong>过程视图</strong></td><td>捕捉设计的<strong>并发和同步</strong>特性</td><td>系统行为特性（动态视角）</td></tr><tr><td><strong>开发视图</strong></td><td>描述开发环境中软件的<strong>静态组织结构</strong></td><td>模块组织</td></tr><tr><td><strong>物理视图</strong></td><td>描述软件到硬件的映射</td><td>部署拓扑</td></tr><tr><td><strong>场景（+1）</strong></td><td><strong>用例视图</strong>，验证其他视图一致性</td><td>统一场景</td></tr></tbody></table><p><strong>视图与视角关系：</strong></p><ul><li><strong>静态视角</strong>（展示功能组织）→ 判断质量特性</li><li><strong>动态视角</strong>（展示并发行为）→ 判断系统行为特性</li><li>四个视图：逻辑视图、进程视图、实现视图、<strong>配置视图</strong></li><li>使用<strong>逻辑视图</strong>记录设计元素的功能和概念接口</li></ul><hr><blockquote><p>多视图体现了<strong>关注点分离</strong>的思想。&quot;4+1&quot;模型中的&quot;1&quot;指的是<strong>统一场景（Use Case）</strong>，将 4 个视图（逻辑视图、进程视图、开发视图、物理视图）串联起来。</p></blockquote><hr><h4 id="软件系统四项基本功能-划分视角" tabindex="-1">软件系统四项基本功能（划分视角） <a class="header-anchor" href="#软件系统四项基本功能-划分视角" aria-label="Permalink to &quot;软件系统四项基本功能（划分视角）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>视角</th><th>关注点</th><th style="text-align:center;">能否判断质量特性</th></tr></thead><tbody><tr><td><strong>静态视角（逻辑视图）</strong></td><td>功能组织</td><td style="text-align:center;">✅</td></tr><tr><td><strong>动态视角（进程视图）</strong></td><td>并发行为 → 系统行为特性</td><td style="text-align:center;">✅</td></tr><tr><td><strong>配置视角（部署视图）</strong></td><td>软件到硬件的映射</td><td style="text-align:center;">❌</td></tr></tbody></table><hr><hr><h3 id="软件复用" tabindex="-1">软件复用 <a class="header-anchor" href="#软件复用" aria-label="Permalink to &quot;软件复用&quot;">​</a></h3><p><strong>机会复用 vs 系统复用：</strong></p><ul><li><strong>机会复用</strong>（发现复用）：开发过程中，只要发现有可复用的资产，就进行复用</li><li><strong>系统复用</strong>（计划复用）：开发之前就进行规划，决定哪些需要复用</li></ul><p><strong>水平式重用 vs 垂直式重用：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>水平式重用</strong></td><td>跨领域通用（应用领域无关），提供基础功能</td><td>标准函数库、通用类库</td></tr><tr><td><strong>垂直式重用</strong></td><td>面向特定领域（领域相关），包含领域知识</td><td>医学词汇表、电子商务标准、网银支付接口</td></tr></tbody></table><p><strong>复用过程的三个主要阶段：</strong></p><ol><li>构造/获取可复用的软件资产</li><li>管理可复用资产</li><li>使用可复用资产</li></ol><hr><h3 id="架构复审与演化" tabindex="-1">架构复审与演化 <a class="header-anchor" href="#架构复审与演化" aria-label="Permalink to &quot;架构复审与演化&quot;">​</a></h3><p><strong>架构复审目的：</strong> 标识潜在风险，及早发现架构设计中的缺陷和错误。复审过程中主要由<strong>用户代表与领域专家</strong>决定架构是否满足需求、质量需求是否在设计中得到体现。</p><p><strong>架构演化：</strong> 针对用户需求变化，修改应用架构满足新的需求。</p><p><strong>架构描述与需求对应：</strong></p><ul><li>架构 → 用<strong>视角与视图</strong>描述</li><li>功能需求 → 用<strong>用例</strong>描述</li><li>质量需求 → 用<strong>质量场景</strong>描述</li></ul><hr><h3 id="构件组装与架构失配" tabindex="-1">构件组装与架构失配 <a class="header-anchor" href="#构件组装与架构失配" aria-label="Permalink to &quot;构件组装与架构失配&quot;">​</a></h3><blockquote><p>🎯 架构失配主要包括三类：<strong>构件失配</strong>（基础设施/控制模型/数据模型冲突）、<strong>连接子失配</strong>（交互协议/数据格式冲突）、<strong>系统成分对全局体系结构的假设冲突</strong>。</p></blockquote><p><strong>失配分类与原因：</strong></p><table tabindex="0"><thead><tr><th>失配类型</th><th>产生原因</th><th>关键词</th></tr></thead><tbody><tr><td><strong>构件失配</strong></td><td>系统对构件基础设施、控制模型和数据模型的假设存在冲突</td><td>基础设施、控制模型、数据模型</td></tr><tr><td><strong>连接子失配</strong></td><td>系统对构件交互协议、构件连接时数据格式的假设存在冲突</td><td>交互协议、数据格式</td></tr><tr><td><strong>全局体系结构失配</strong></td><td>系统成分对全局体系结构的假设存在冲突</td><td>整体架构假设</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：<strong>由构件操作不当引起的失配</strong>不属于构件组装阶段的失配问题。</p></blockquote><hr><h3 id="软件系统四大基本功能-三硬件构件-架构设计核心模型" tabindex="-1">软件系统四大基本功能 + 三硬件构件（架构设计核心模型） <a class="header-anchor" href="#软件系统四大基本功能-三硬件构件-架构设计核心模型" aria-label="Permalink to &quot;软件系统四大基本功能 + 三硬件构件（架构设计核心模型）&quot;">​</a></h3><blockquote><p>🎯 软件系统可分为四项基本功能，硬件有三类主要构件。架构设计的首要步骤是将<strong>非功能需求</strong>细化为更详细的需求。</p></blockquote><p><strong>软件系统四大基本功能（自上而下）：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>英文</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据存储</strong></td><td>Data Storage</td><td>存储和检索数据，无论是小文件还是大数据库</td></tr><tr><td><strong>数据访问逻辑</strong></td><td>Data Access Logic</td><td>处理访问数据的过程，通常指 SQL 查询</td></tr><tr><td><strong>应用逻辑</strong></td><td>Application Logic</td><td>DFD、用例和功能需求中记录的业务逻辑</td></tr><tr><td><strong>表示逻辑</strong></td><td>Presentation Logic</td><td>向用户显示信息并接收用户命令</td></tr></tbody></table><p><strong>系统三类主要硬件构件：</strong></p><blockquote><p>🎯 客户端（Clients）、服务器（Servers）、网络（Network）。</p></blockquote><hr><h3 id="设计模式三分类" tabindex="-1">设计模式三分类 <a class="header-anchor" href="#设计模式三分类" aria-label="Permalink to &quot;设计模式三分类&quot;">​</a></h3><blockquote><p>🎯 设计模式按目的分为：<strong>创建型</strong>（对象实例化）、<strong>结构型</strong>（类/对象组合）、<strong>行为型</strong>（类/对象交互）。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>核心关注</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>创建型</strong></td><td>对象实例化过程的抽象</td><td>单例（Singleton）、工厂方法</td></tr><tr><td><strong>结构型</strong></td><td>类或对象的组合方式</td><td>适配器（Adapter）、桥接（Bridge）</td></tr><tr><td><strong>行为型</strong></td><td>类或对象之间的交互和职责分配</td><td>策略（Strategy）、观察者（Observer）</td></tr></tbody></table><blockquote><p>🎯 Bridge 模式 = 将抽象与实现分离；Strategy 模式 = 算法族可互换使用。飞机模拟系统中飞行行为与起飞行为的解耦是 <strong>Strategy 模式</strong>。</p></blockquote>',65)])])}const c=r(d,[["render",l]]);export{p as __pageData,c as default};
